mapper.select:
SELECT COALESCE(SUM(i.count), 0)
FROM trade_order_item i
INNER JOIN trade_order o ON o.id = i.order_id AND o.deleted = 0
WHERE i.deleted = 0
  AND i.user_id = #{userId}
  AND i.subscription_student_id = #{studentId}
  AND i.subscription_offer_sku_id = #{offerSkuId}
  AND o.status <> #{canceledStatus}

mapper.sql:
FROM trade_order_item i
INNER JOIN trade_order_delivery d ON d.id = i.delivery_id AND d.deleted = FALSE
INNER JOIN trade_order o ON o.id = i.order_id AND o.deleted = FALSE
WHERE i.deleted = FALSE
  AND d.biz_scene = #{bizScene}
  AND d.delivery_type = #{deliveryType}
  AND d.status = #{deliveryStatus}
  AND o.status = #{orderStatus}
  AND o.refund_status = #{refundStatus}
  AND i.subscription_window_id IS NOT NULL
  AND i.subscription_offer_id IS NOT NULL
  AND i.subscription_offer_sku_id IS NOT NULL
  AND (i.publication_delivery_status IS NULL OR i.publication_delivery_status = #{publicationDeliveryStatus})

  AND d.school_id = #{reqVO.schoolId}


  AND d.station_id = #{reqVO.stationId}


  AND i.subscription_window_id = #{reqVO.windowId}


  AND i.subscription_offer_id = #{reqVO.offerId}


  AND i.subscription_offer_sku_id = #{reqVO.offerSkuId}


  AND i.sku_id = #{reqVO.skuId}
